INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('2', 'Business', '', '0', '0', '0', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('1', 'Scheduler', 'The scheduler of the program: the tasks and the feed of notes under every one of them - the same lists the owner and the staff see in their windows. Add-only, the way the program keeps it: a task is never edited nor deleted, it moves by a note carrying a state, and kClose ends it. A private task is seen by its author, its executor and the person with id 1. state_key and kind_key are values of TASK_STATE_KEY and TASK_KIND_KEY in the base settings, and the people go by id - the Users tool answers them.', '2', '1', '1', '0', 'melbis_agent_task.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('33', 'Currencies', 'The currencies the prices of the store are written in. multiplex is the rate against the base currency - the one whose rate is 1 - and division says a sum is divided by that rate instead of multiplied. A goods points at a currency by its *_curr_id columns and the Price tool writes them; the sums already written into orders keep their own words and never follow a currency.', '2', '1', '2', '0', 'melbis_agent_currency.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('34', 'Providers', 'The providers of the goods, the groups they stand in and the options hung on them. The option tree - provider_key with the values of provider_key_value - belongs to the program and is only read here; the providers, their groups and the rows of provider_key_set are what this tool writes. A goods points at its provider by store.provider_id, the Price tool writes it, and a currency of one provider points back by currency.provider_id.', '2', '1', '3', '0', 'melbis_agent_provider.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('35', 'Discounts', 'The discount groups of the store and the rules standing in them. A goods carries a group by store.disc_group_id - the Price tool writes it - and the rules of that group say what the discount is: from_sum is where a rule starts, disc_proc is how much it takes off, and the two days are the ones it lives between. A group holding no rule gives nothing away. A rule writes its currency in sum_curr_id, and the Currencies tool answers those.', '2', '1', '4', '0', 'melbis_agent_disc.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('43', 'Taxes', 'The taxes of the store. A group holds the rates, and a goods points at a group by its tax_group_id - the Price tool writes that column, not this one. The areas are a tree of their own - a country, a region inside it - and a rule is what ties a rate to an area; a rule may carry a value of its own instead of the one its rate names. The options declared for the areas live in the registry of the additional options, place tax_area, and only the rows set on the areas are written here.', '2', '1', '5', '0', 'melbis_agent_tax.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('46', 'Orders', 'The orders of the shop. An order is never changed in place: every change is a new version of it, and the version the order stands at now is the one the shop shows. CmdQuery finds and reads orders whole. The work on one order walks in a circle: CmdLoad answers its version as one array - or CmdCreate answers a blank one - the array is shaped in your hands or by the goods and option commands, CmdCalc counts the money the way the shop counts it, and CmdEdit saves the array as the new version of the order. Every step of the circle passes through the very logic the storefront checkout runs - the discounts, the option sums, the refusals of the shop included - and never straight into the tables. The right to see an order goes by the values of its options, a status among them; saving takes the ORDER_VERSION_ADD operation of the store.', '2', '1', '6', '0', 'melbis_agent_orders.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('9', 'Products', '', '0', '0', '7', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('12', 'Brands', 'The brands of the goods and the options hung on them. The option tree - brand_key with the values of brand_key_value - belongs to the program and is only read here; the brand rows and the rows of brand_key_set are what this tool writes. A goods wears a brand by its brand_id column, and the Price tool writes it.', '9', '1', '8', '0', 'melbis_agent_brand.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('30', 'Goods', '', '9', '1', '9', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('29', 'Browser', 'The catalogue as the Browser window shows it, read and never written: the goods of a section or of a whole branch, and the search by any column the sign names. A goods comes with the twenty-one columns that window loads - what it is called, what it costs, its codes, its clan, its days - and with the sections it hangs in. Everything else about a goods belongs to the other tools of the Goods branch: the prices and the stock to Price, the texts to Description, the place in a section to Place. The right is for_browse, given out in the program on the sections a goods hangs in.', '30', '2', '10', '0', 'melbis_agent_store_browse.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('15', 'Price', 'The commercial half of a goods: what it costs and how many there are - the prices with their currencies, the supplier, the discount group, the tax group, the stock and the counts on the warehouses, the auto-count, and the parameters standing on it. The right is for_price, given out in the program on the sections a goods hangs in, so only goods hanging in a section of yours are reached here. The other half - the names and the texts a buyer reads - belongs to the Description tool.', '30', '2', '11', '0', 'melbis_agent_store_price.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('14', 'Description', 'The content half of a goods: what a buyer reads about it - the names, the codes, the texts, the seo, the clan and the characteristics standing on it. The very fields the Description window of the program writes back, the price among them, though the money proper belongs to the Price tool. The right is for_frame, given out in the program on the sections a goods hangs in, so only goods hanging in a section of yours are reached here.', '30', '2', '12', '0', 'melbis_agent_store_descr.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('23', 'Place', 'Where a goods hangs in the catalogue and in what order it stands there - the rows of topic_store and nothing else. The right is the place one, given out on the section: the section takes the goods in, so whoever owns the section decides. A goods hanging in no section is in the store and in no catalogue at all, and only the Lost tool reaches it.', '30', '2', '13', '0', 'melbis_agent_store_place.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('24', 'Lost', 'The goods that hang in no section: a goods loses its last section and drops out of every window that walks the catalogue - this is where it is found again. From here it goes back into a section, or out of the store for good. Deleting a goods happens nowhere else, and it goes by the operations of a person, not by the right of a section: a goods hanging nowhere has no section to hold a right.', '30', '2', '14', '0', 'melbis_agent_store_lost.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('39', 'Import', '', '9', '1', '15', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('37', 'Goods', 'The loader of the goods: everything a card is made of in one call. Four streams tied by ref, a temporary key of your own - the goods, their characteristics, their parameters, and the sections they hang in. Keys are not weighed here: brands, providers, currencies and the tree of the characteristics are read beforehand and come as ids; only a value of a characteristic may come as a word, and it is looked up under its info_id. The pictures are a call of their own: the store lays a file down before a module runs, and a goods not born yet has nothing to hang it on - take the ids of this answer to the Files tool.', '39', '2', '16', '0', 'melbis_agent_import_goods.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('38', 'Files', 'The loader of the files: a pack of them onto the elements in one call, and a derived picture painted beside those that ask for one. It is the second half of an import and goes after the goods: a file hangs on an element by its id, and the ids are what the answer of the Goods loader gave back - write them into the rows of this call. The files themselves ride with the call, so the size of one pack is the size of one request: split a big load into several calls.', '39', '2', '17', '0', 'melbis_agent_import_files.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('6', 'Structure', '', '0', '0', '18', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('8', 'Catalog', 'The sections of the main catalogue: the tree itself, the rights on it, the options hung on it and the alternative catalogues built over it. Every row of an answer says what this person may do on that very section, so read the list before promising anything. The goods themselves are not touched here - only the places they hang in, and the Place tool moves them.', '6', '1', '19', '0', 'melbis_agent_topic.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('10', 'Attributes', 'What a buyer reads about a goods: the tree of the characteristics with its folders, and the values every one of them takes. The tree comes whole, the values are asked for by their characteristic - a live shop keeps thousands of them. The rights are a pair - the characteristic itself and its values - and they are given out on the characteristic, in the program.', '6', '1', '20', '0', 'melbis_agent_info.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('11', 'Parameters', 'The parameters of the goods: the commercial properties the prices are built of - warranty, delivery, a margin of its own - and the values each one takes, every value with the sum it carries and the currency of that sum. Not what a buyer reads about the goods: that is the characteristics, and the Attributes tool keeps them.', '6', '1', '21', '0', 'melbis_agent_param.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('45', 'Promo blocks', 'The promo blocks of the shop: a tree of blocks, and under every one of them the texts it shows, the goods it gathers, the places it hangs in and the option rows set on it. The types - kind_key here, obj_key on a link - are values of ADVERT_KIND_KEY, ADVERT_TEXT_KIND_KEY, ADVERT_GOODS_KIND_KEY, ADVERT_LINK_KIND_KEY and ADVERT_LINK_OBJ_KEY in the base settings, and the Settings tool answers them. The pictures of a text belong to the Files tool, element advert_text.', '6', '1', '22', '0', 'melbis_agent_advert.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('42', 'Settings', 'The settings the people of the shop change themselves - the window of the program calls them Settings. What a setting is and where it stands is declared by the developer in the registry, and the User settings tool keeps that; here only the value moves. A person changes a setting when the branch it stands on was given to them or to their group, and CmdList says of every setting whether this person may.', '6', '1', '23', '0', 'melbis_agent_user_key.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('21', 'Files', '', '0', '0', '24', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('22', 'File', 'The files of the elements - the photographs of the goods above all. One tool for every element, because one table shape serves them all: a file is a row of files_<entity> and a picture on the disk. The group of a file (kind_key) is what a template picks it by, and the group words are values of the FILES_<ENTITY> codes in the base settings. The right is that of the element the file hangs on. No tool deletes a picture from the disk: rows go, and the idle-files audit of the owner reclaims the space.', '21', '1', '25', '0', 'melbis_agent_file.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('27', 'Profile', 'The picture profiles: the recipes a derived picture is made by - size, type, quality, margins, background, rotation, mask, effects. A profile is a row of the FILES_PROFILE dictionary, but its body is XML of the program\'s editor, so it is read and written here, in plain words. The frame of a picture is cut by hand in the program; everything else a profile keeps. A mask is a value of FILES_MASK in the base settings with a picture hung on it by the Files tool - entity key_value, elem_id the id of that value.', '21', '1', '26', '0', 'melbis_agent_file_profile.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('7', 'Development', '', '0', '0', '27', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('5', 'Settings', 'The registry of the settings of this shop: the base lists the whole program picks from, and the settings the people of the shop change themselves.', '7', '1', '28', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('31', 'Basic settings', 'The base settings of the shop: the tree of the codes and the values every code keeps - the lists the whole program picks from, from the kind of a goods to the style of a section. The tree of the codes belongs to the platform and is only read; the values are what this tool writes. A value marked sys_key is one the platform relies on by its very name: its text may be changed, but not that name, and it cannot be removed.', '5', '2', '29', '0', 'melbis_agent_key_value.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('32', 'User settings', 'The settings the people of the shop change themselves: the groups in a tree, and in every group the settings with the mask their text is typed by, plus the rights that say who sees a group. What the storefront reads out of them is the business of the modules.', '5', '2', '30', '0', 'melbis_agent_self_key.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('40', 'Additional options', 'The registry of the additional options: what may be hung on the rows of an entity - sections, attributes, brands, suppliers and their warehouses, parameters and their values, people, groups of people, promo blocks, filters and tax areas. Every call names its place, and the answer is the tree of the options declared there with the values every one of them keeps. Setting an option on a row of an entity is not done here: the tool of that family writes its own *_key_set and takes key_id and value_id from this one. An option is addressed by its skey, in a module as in the program, so two of one name in one place are refused.', '5', '2', '31', '0', 'melbis_agent_option.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('41', 'Custom filters', 'The filters an operator picks in the window that asks the server for data: a filter is a query of the developer answering the ids of its place - the goods, the orders or the customers. A parameter written as :NAME in that query is asked for when the filter is used; :NAME@ALIAS is picked from a value list instead of typed, and those lists are the second table here - their own queries run against the local base of the program and answer ID and NAME.', '5', '2', '32', '0', 'melbis_agent_user_filter.php');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('3', 'System', '', '0', '0', '33', '1', '');
INSERT INTO {DBNICK}_agent_tool (id, name, descr, tindex, tlevel, absindex, folder, unit) VALUES ('4', 'Users', 'The people of the shop, the groups they stand in and the rights they hold - a right is an operation of the oper tree, handed to a person or to a group. A password is never a field of a call: it is born in the tool, kept as md5 and said once. What a person did in the shop keeps their id, so one who carries history is blocked rather than deleted.', '3', '1', '34', '0', 'melbis_agent_user.php');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('257', '1', 'CmdList', 'Reads every task this person may see, the closed ones too - kClose tells them apart - and counts the notes of each, so a feed is asked for knowingly.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('258', '1', 'CmdAdd', 'Adds a task and opens its feed with the first note, the way the program opens one. The person of this session signs as the author, and the state at birth is kNew.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('259', '1', 'CmdNoteList', 'Reads the feed of a task whole, the notes in the order they were written.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('260', '1', 'CmdNoteAdd', 'Writes a note into the feed of one task; the state says whether the task moves with it - kComment leaves it where it stands, any other state moves it and kClose ends it. exec_id, kind_key and privy given here move with the task.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('222', '4', 'CmdListCut', 'Reads the people and the groups they stand in - two tables. The tree of the operations and the rights given out come with CmdListFull. The password of a person is answered by neither: it is kept as md5 and said once, when it is made.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('359', '4', 'CmdListFull', 'Reads the people and their groups together with the tree of the operations, the rights given out and the tables every operation touches - five tables in one answer.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('223', '4', 'CmdAdd', 'Adds a person. There is no password field: the tool makes one, keeps its md5 only and says the password once in the answer - hand it over, advise to change it, store it nowhere. Rights are given out with CmdRightAdd.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('224', '4', 'CmdUpdate', 'Changes the columns given of people, by id - what the call leaves out stays as it was. A login changes for one person at a time, and blocking is here too: is_blocked.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('225', '4', 'CmdRemove', 'Deletes people by id, with the rows of their rights. A person who carries history - tasks, notes, memory - is refused: block them instead. The person of this session is refused too.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('226', '4', 'CmdPassword', 'Makes a new password for one person, said once and kept as md5 only. The old one stops working at once.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('227', '4', 'CmdGroupAdd', 'Adds a group of people at the end of the list. Its rights are given out with CmdRightAdd.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('228', '4', 'CmdGroupUpdate', 'Changes the columns given of groups, by id - what the call leaves out stays as it was.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('229', '4', 'CmdGroupRemove', 'Deletes groups by id, with the rows of their rights. A group that people still stand in is refused - move them out of it first.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('230', '4', 'CmdGroupPos', 'Lays the list of the groups in order.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('231', '4', 'CmdRightAdd', 'Grants an operation to a person or to a group, one of the two - the other stays empty. A right by group reaches everyone whose group_id or add_group_id it is. The person with id 1 holds every operation without a single row here, and the oper tree itself belongs to the engine: no tool writes it.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('232', '4', 'CmdRightUpdate', 'Changes the columns given of the right rows, by id. A right does not move from a person to a group: take it back and give it out anew.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('233', '4', 'CmdRightRemove', 'Takes rights back by id. The other rights of those people stay.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('360', '4', 'CmdKeyAdd', 'Sets an option on people: one row of user_key_set on every person named. The options themselves are declared in the registry of the additional options, place user, and that tool answers their tree.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('361', '4', 'CmdKeyUpdate', 'Changes the columns given of the rows of user_key_set, by id - what the call leaves out stays as it was.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('362', '4', 'CmdKeyRemove', 'Deletes the rows of user_key_set by id. The option itself stays in its tree.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('363', '4', 'CmdGroupKeyAdd', 'Sets an option on groups of people: one row of user_group_key_set on every group named. The options are declared in the registry of the additional options, place user_group.', '17');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('364', '4', 'CmdGroupKeyUpdate', 'Changes the columns given of the rows of user_group_key_set, by id.', '18');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('365', '4', 'CmdGroupKeyRemove', 'Deletes the rows of user_group_key_set by id. The option itself stays in its tree.', '19');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('151', '8', 'CmdListCut', 'Reads the sections of the catalogue and nothing beside them. The rights, the alternative catalogues and the option rows come with CmdListFull.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('366', '8', 'CmdListFull', 'Reads the catalogue whole - the sections, the rights standing on them, the nodes of every alternative catalogue and the option rows set: four tables in one answer.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('152', '8', 'CmdAdd', 'Adds a section under a parent. The rights of the parent are copied onto it, so the same people own it; the parent itself must be yours to shape.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('153', '8', 'CmdUpdate', 'Changes the columns given of sections, by id - what the call leaves out stays as it was.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('154', '8', 'CmdMove', 'Moves a section under another parent, with its whole branch. Both the section and the new parent must be yours to shape, and a section cannot move inside its own branch.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('155', '8', 'CmdRemove', 'Deletes sections by id, with everything lying under them. The first call counts the sections and the goods it touches, the second one does it: the goods stay in the store, and the ones left hanging nowhere are reached by the Lost tool alone.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('156', '8', 'CmdRightAdd', 'Grants a right on sections, to a person or to a group: one row of topic_right on each of them. One of user_id and group_id, never both.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('157', '8', 'CmdRightUpdate', 'Changes the columns given of the rows of topic_right, by id - CmdList answers them with their ids.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('158', '8', 'CmdRightRemove', 'Deletes the rows of topic_right by id. A section left with no rights on it is seen only by whoever holds PUT_TOPIC_RIGHT.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('159', '8', 'CmdKeyAdd', 'Sets an option on sections: one row of topic_key_set on each of them. The option and its value must stand in the tree of the section options, and a stray id is refused; the sections must be yours to shape.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('160', '8', 'CmdKeyUpdate', 'Changes the columns given of the rows of topic_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('161', '8', 'CmdKeyRemove', 'Deletes the rows of topic_key_set by id. The option itself stays in the registry.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('162', '8', 'CmdAltAdd', 'Adds a node of an alternative catalogue under a parent of the same catalogue. Every node stands for a section of the main catalogue - the name may differ, the section may not be missing, and a node pointing at nothing is swept away.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('163', '8', 'CmdAltUpdate', 'Changes the columns given of the nodes of the alternative catalogues, by id.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('164', '8', 'CmdAltMove', 'Moves a node of an alternative catalogue under another parent of the same catalogue, its branch with it. The node and the parent are named by id, and kind_key says which catalogue they belong to; 0 as a parent puts the node at the top.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('165', '8', 'CmdAltRemove', 'Deletes nodes of one alternative catalogue with the branches under them. The first call counts what goes, depend does it. The sections they point at stay as they are.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('176', '10', 'CmdListCut', 'Reads the tree of the characteristics and nothing beside it. The rights and the option rows come with CmdListFull; the values of a characteristic come with CmdValueList - a live shop keeps thousands of them.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('367', '10', 'CmdListFull', 'Reads the tree of the characteristics together with the rights standing on them and the option rows set: three tables in one answer. The values are asked for by CmdValueList.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('177', '10', 'CmdAdd', 'Adds a characteristic under a parent, or at the top of the tree when parent_id is 0. The rights of the parent are copied onto it.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('178', '10', 'CmdUpdate', 'Changes the columns given of characteristics, by id - what the call leaves out stays as it was.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('179', '10', 'CmdMove', 'Moves a characteristic under another parent, with its whole branch.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('180', '10', 'CmdRemove', 'Deletes characteristics by id, with the branch under them, their values and the links of the goods to those values. The first call counts what goes, the second one does it.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('181', '10', 'CmdValueList', 'Reads the values of characteristics, or the values themselves by id. One of info_id and id is asked for: nothing answers every value of the shop.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('182', '10', 'CmdValueAdd', 'Adds a value to a characteristic, at the end of its list.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('183', '10', 'CmdValueUpdate', 'Changes the columns given of values, by id - what the call leaves out stays as it was.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('184', '10', 'CmdValueRemove', 'Deletes values by id, with the links of the goods to them - the characteristic itself stays. The first call counts what goes, the second one does it.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('185', '10', 'CmdValuePos', 'Lays the values of one characteristic in order.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('186', '10', 'CmdRightAdd', 'Grants a right on characteristics, to a person or to a group: one row of info_right on each of them. One of user_id and group_id, never both.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('187', '10', 'CmdRightUpdate', 'Changes the columns given of the rows of info_right, by id - CmdList answers them with their ids.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('188', '10', 'CmdRightRemove', 'Deletes the rows of info_right by id.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('189', '10', 'CmdKeyAdd', 'Sets an option on characteristics: one row of info_key_set on each of them. The option and its value must stand in the tree of the characteristic options, and a stray id is refused.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('190', '10', 'CmdKeyUpdate', 'Changes the columns given of the rows of info_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('191', '10', 'CmdKeyRemove', 'Deletes the rows of info_key_set by id. The option itself stays in the registry.', '17');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('167', '11', 'CmdListCut', 'Reads the parameters together with all their values - two tables. The option rows standing on parameters and on values come with CmdListFull.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('368', '11', 'CmdListFull', 'Reads the parameters, their values and the option rows standing on both - four tables in one answer.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('168', '11', 'CmdAdd', 'Adds a parameter at the end of the list. fixed_set keeps the goods to the values of its list and nothing of their own; custom_sum lets the sum be changed on the goods.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('169', '11', 'CmdUpdate', 'Changes the columns given of parameters, by id - what the call leaves out stays as it was.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('170', '11', 'CmdRemove', 'Deletes parameters by id, with their values and the links of the goods to them. The first call counts what goes, the second one does it; the prices built on those sums change.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('171', '11', 'CmdPos', 'Lays the list of the parameters in order.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('172', '11', 'CmdValueAdd', 'Adds a value to a parameter, at the end of its list.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('173', '11', 'CmdValueUpdate', 'Changes the columns given of values, by id - what the call leaves out stays as it was.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('174', '11', 'CmdValueRemove', 'Deletes values by id, with the links of the goods to them - the parameter itself stays. The first call counts what goes, the second one does it; the prices built on those sums change.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('175', '11', 'CmdValuePos', 'Lays the values of one parameter in order.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('369', '11', 'CmdKeyAdd', 'Sets an option on parameters: one row of param_key_set on every parameter named. The options are declared in the registry of the additional options, place param.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('370', '11', 'CmdKeyUpdate', 'Changes the columns given of the rows of param_key_set, by id - what the call leaves out stays as it was.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('371', '11', 'CmdKeyRemove', 'Deletes the rows of param_key_set by id. The option itself stays in its tree.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('372', '11', 'CmdValueKeyAdd', 'Sets an option on the values of the parameters: one row of param_value_key_set on every value named. The options are declared in the registry of the additional options, place param_value.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('373', '11', 'CmdValueKeyUpdate', 'Changes the columns given of the rows of param_value_key_set, by id.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('374', '11', 'CmdValueKeyRemove', 'Deletes the rows of param_value_key_set by id. The option itself stays in its tree.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('239', '12', 'CmdListCut', 'Reads the brands and nothing beside them. The rows of brand_key_set standing on them come with CmdListFull.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('353', '12', 'CmdListFull', 'Reads the brands together with the rows of brand_key_set standing on them - two tables in one answer.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('240', '12', 'CmdAdd', 'Adds a brand at the end of the list.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('241', '12', 'CmdUpdate', 'Changes the columns given of brands, by id - what the call leaves out stays as it was.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('242', '12', 'CmdRemove', 'Deletes brands by id. The first call counts the goods wearing them, the second one does it: the goods stay in the store with an emptied brand_id, and what hung on the brands - the option rows and the file rows - is swept by the map of the engine.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('243', '12', 'CmdPos', 'Lays the list of the brands in order.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('244', '12', 'CmdKeyAdd', 'Sets an option on brands: one row of brand_key_set on each of them. The option and its value must stand in the tree of the brand options, and a stray id is refused.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('245', '12', 'CmdKeyUpdate', 'Changes the columns given of the rows of brand_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('246', '12', 'CmdKeyRemove', 'Deletes the rows of brand_key_set by id. The option itself stays in the tree.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('142', '14', 'CmdTopic', 'Walks the goods of the sections named - the plain way to see what stands where. Searching by the columns of the map is CmdQuery.\n\nName the sections in topic_id, and topic_sub takes the whole branch under each of them; the Catalog tool answers the tree to pick them from. A section this person may not price is walked past, whatever the call names.\n\nThe goods come by id, and so does every page of them: a walk of many pages loses none and says none twice. Where a goods stands and at what place comes with it, in the rows of topic_store - sort by that if the order of the shop is what is wanted.\n\nA goods hanging in several of the sections walked is answered once. The answer is the one CmdQuery gives: the goods, the sections they hang in, their characteristics, the objects tied to them - and found, the whole count of what stands there, whatever the page asked for.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('348', '14', 'CmdQuery', 'Finds the goods by a query written as json and answers them with everything that hangs on them - the goods, the sections they hang in, their characteristics, the objects tied to them.\n\nASKED FOR NOTHING - an empty query, or none at all - it answers its own signature instead: every table with every column and its type, and what may be asked of each. Nothing outside that list is taken, so a first call asks for it and the ones after are built by it.\n\nTHE SHAPE. A query starts from the root table of the sign and holds a list of conditions. A list is an AND, always. Four things may stand in it:\na condition - {"field": "price", "op": "between", "value": [1000, 5000]};\nan or - {"or": [ ..., ... ]};\na not - {"not": ...}, of one condition or of one nested table;\na nested table - {"topic_store": [ ... ]}, which means THERE IS such a row: every condition inside it holds on one and the same row. A table goes one level deep only, and only a table the sign marks nest.\n\nTHE SECTIONS are a nested table like any other: {"topic_store": [{"field": "topic_id", "op": "in", "value": [9, 10]}]}. The sections are named as they are - a whole branch is named section by section, and the Catalog tool answers the tree to build such a list from.\n\nNOTHING STANDS BESIDE THE ROOT TABLE. The page is a field of the call - limit and offset - and the goods come by id, page after page, so a walk of many pages loses none and says none twice. Sorting them any other way is done by whoever reads the answer. Whatever the page, the answer carries found - the whole count of what matched - so the size of a search is known without pulling it.\n\nTHE OPERATIONS come from the type of the column, and the sign names them: eq, in, between, ge, le for numbers, eq, between, ge, le for days, eq, in, like for words, eq for flags. between takes two values, in takes a list, the rest take one. like looks for a part of the text anywhere in it.\n\nAN EXAMPLE of the whole thing:\n{"store": [\n  {"field": "no_visible", "op": "eq", "value": false},\n  {"field": "price", "op": "between", "value": [1000, 5000]},\n  {"or": [ {"field": "status_key", "op": "in", "value": ["kExist", "kExistOrder"]},\n            {"field": "brand_id", "op": "in", "value": [1, 2]} ]},\n  {"topic_store": [ {"field": "topic_id", "op": "in", "value": [9, 10, 11]} ]},\n  {"store_info": [ {"field": "info_id", "op": "eq", "value": 1},\n                   {"field": "value_id", "op": "eq", "value": 2} ]},\n  {"not": {"store_set": [ {"field": "obj_key", "op": "eq", "value": "kStore" } ]}}\n]}\n\nThe goods of a list of ids are asked for the same way: {"store": [ {"field": "id", "op": "in", "value": [25, 26]} ]}.\n\nThe right stands beside the query and is not part of it: only the goods hanging in a section this person may describe are ever met, whatever the query says. The place a goods keeps in a section is answered here but never written - the Place tool shapes that, and what a goods costs belongs to Price.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('166', '14', 'CmdAdd', 'Adds a goods and hangs it in the section at once - a goods hanging nowhere is seen by the Lost tool alone. Every column of the half may come in the same call; the days left out are stamped now, and a fresh goods is born hidden, out of stock and plain. The section must be yours to describe.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('143', '14', 'CmdUpdate', 'Changes the columns given, on one goods or on several at once - each of them gets the same written. What the call leaves out stays as it was, and update_time and edit_time are stamped now unless the call carries its own. A goods hanging in no section of yours is refused by id.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('144', '14', 'CmdInfoAdd', 'Sets a characteristic on goods: one row of store_info on each of them, and a characteristic holding several values at once takes a row for each. The characteristic itself comes from the Attributes tool - a value of its list goes by value_id, a number by value_dec, a text of your own by value_txt.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('145', '14', 'CmdInfoUpdate', 'Changes the columns given of the rows of store_info; a row keeps whatever the call leaves out. CmdTopic answers the rows of a goods with their ids.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('146', '14', 'CmdInfoRemove', 'Deletes the rows of store_info by id. The characteristic itself stays in the store, and the goods keeps the other ones standing on it.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('147', '14', 'CmdSetAdd', 'Ties another object of the store to goods: one row of store_set on each of them. obj_key says what is tied - a goods or a section - and kind_key what the tie means; the storefront reads that: accessories, a kit, a section to send to.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('148', '14', 'CmdSetUpdate', 'Changes the columns given of the rows of store_set; a row keeps whatever the call leaves out. CmdTopic answers the rows of a goods with their ids.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('149', '14', 'CmdSetRemove', 'Deletes the rows of store_set by id. The object it tied stays in the store.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('150', '14', 'CmdClannNew', 'Makes a fresh clan over the goods named and answers its number: a clan holds the variants of one thing - the sizes of a shirt, the colours of a cup - and the storefront shows them as one card. root names the goods that leads it, and left out the first of the named leads. A goods already in another clan changes clans. CmdUpdate with clann puts one more goods into a clan that stands.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('336', '15', 'CmdTopic', 'Walks the goods of the sections named - the plain way to see what stands where. Searching by the columns of the map is CmdQuery.\n\nName the sections in topic_id, and topic_sub takes the whole branch under each of them; the Catalog tool answers the tree to pick them from. A section this person may not price is walked past, whatever the call names.\n\nThe goods come by id, and so does every page of them: a walk of many pages loses none and says none twice. Where a goods stands and at what place comes with it, in the rows of topic_store - sort by that if the order of the shop is what is wanted.\n\nA goods hanging in several of the sections walked is answered once. The answer is the one CmdQuery gives: the goods, the sections they hang in, their parameters, their counts on the warehouses - and found, the whole count of what stands there, whatever the page asked for.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('335', '15', 'CmdQuery', 'Finds the goods by a query written as json and answers them with everything that hangs on them - the goods, the sections they hang in, their parameters, their counts on the warehouses.\n\nASKED FOR NOTHING - an empty query, or none at all - it answers its own signature instead: every table with every column and its type, and what may be asked of each. Nothing outside that list is taken, so a first call asks for it and the ones after are built by it.\n\nTHE SHAPE. A query starts from the root table of the sign and holds a list of conditions. A list is an AND, always. Four things may stand in it:\na condition - {"field": "price", "op": "between", "value": [1000, 5000]};\nan or - {"or": [ ..., ... ]};\na not - {"not": ...}, of one condition or of one nested table;\na nested table - {"topic_store": [ ... ]}, which means THERE IS such a row: every condition inside it holds on one and the same row. A table goes one level deep only, and only a table the sign marks nest.\n\nTHE SECTIONS are a nested table like any other: {"topic_store": [{"field": "topic_id", "op": "in", "value": [9, 10]}]}. The sections are named as they are - a whole branch is named section by section, and the Catalog tool answers the tree to build such a list from.\n\nNOTHING STANDS BESIDE THE ROOT TABLE. The page is a field of the call - limit and offset - and the goods come by id, page after page, so a walk of many pages loses none and says none twice. Sorting them any other way is done by whoever reads the answer. Whatever the page, the answer carries found - the whole count of what matched - so the size of a search is known without pulling it.\n\nTHE OPERATIONS come from the type of the column, and the sign names them: eq, in, between, ge, le for numbers, eq, between, ge, le for days, eq, in, like for words, eq for flags. between takes two values, in takes a list, the rest take one. like looks for a part of the text anywhere in it.\n\nAN EXAMPLE of the whole thing:\n{"store": [\n  {"field": "no_visible", "op": "eq", "value": false},\n  {"field": "price", "op": "between", "value": [1000, 5000]},\n  {"or": [ {"field": "status_key", "op": "in", "value": ["kExist", "kExistOrder"]},\n            {"field": "how", "op": "ge", "value": 1} ]},\n  {"topic_store": [ {"field": "topic_id", "op": "in", "value": [9, 10, 11]} ]},\n  {"store_param": [ {"field": "param_id", "op": "eq", "value": 1},\n                    {"field": "value_id", "op": "eq", "value": 2} ]},\n  {"not": {"store_stock": [ {"field": "provider_stock_id", "op": "eq", "value": 9},\n                            {"field": "how", "op": "eq", "value": 0} ]}}\n]}\n\nThe goods of a list of ids are asked for the same way: {"store": [ {"field": "id", "op": "in", "value": [25, 26]} ]}.\n\nThe right stands beside the query and is not part of it: only the goods hanging in a section this person may price are ever met, whatever the query says. The place a goods keeps in a section is answered here but never written - the Place tool shapes that.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('129', '15', 'CmdAdd', 'Adds a goods and hangs it in the section at once - a goods hanging nowhere is seen by the Lost tool alone. Every column of the half may come in the same call, and what the call does not name a fresh goods is born with: the days stamped now, hidden from the storefront, out of stock, of the plain kind and the plain view. The section must be yours to price.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('73', '15', 'CmdUpdate', 'Changes the columns given, on one goods or on several at once - each of them gets the same written. What the call leaves out stays as it was, and update_time is stamped now unless the call carries its own. A goods hanging in no section of yours is refused by id.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('131', '15', 'CmdParamAdd', 'Sets a parameter on goods: one row of store_param on each of them. A value of the parameter\'s own list goes by value_id, a value of your own by value_name. A goods already carrying that parameter takes a second row - read first if that matters.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('132', '15', 'CmdParamUpdate', 'Changes the columns given of the rows of store_param; a row keeps whatever the call leaves out. CmdTopic and CmdQuery answer the rows of a goods with their ids. Only the id of a row is fixed: store_id moves the row to another goods and param_id makes it another parameter, and a goods it moves to is weighed by the same right.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('133', '15', 'CmdParamRemove', 'Deletes the rows of store_param by id. The parameter itself stays in the store and the goods keeps its other parameters.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('337', '15', 'CmdStockAdd', 'Puts goods on a warehouse: one row of store_stock on each of the goods named, with the count they hold there. The warehouses themselves belong to the Providers tool, and it answers their ids. A goods already standing on that warehouse takes a second row - read first if that matters.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('338', '15', 'CmdStockUpdate', 'Changes the columns given of store_stock rows, by id - CmdTopic and CmdQuery answer them with their ids. A row keeps whatever the call leaves out. Only the id of a row is fixed: store_id moves the row to another goods, weighed by the same right, and provider_stock_id moves it to another warehouse.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('339', '15', 'CmdStockRemove', 'Deletes store_stock rows by id. The goods and the warehouse stay as they are; only the count on that warehouse is gone.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('247', '22', 'CmdList', 'Reads the files of elements - whole rows of files_<entity>, in the order a template walks them. Takes the right of those elements.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('248', '22', 'CmdAdd', 'Hangs the files that ride with the call on their elements: every entry carries its path, its entity and its elem_id, and may carry kind_key and real_name. The store lays each file down before the tool runs and weighs the group by the registry; the picture is kept as it came - nothing here resizes or crops it. Takes the right of the elements.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('249', '22', 'CmdMake', 'Paints a second picture out of one already in the store, by a profile of the Profiles tool: fitted into its box, the canvas behind, the mask over, the effects GD paints. What GD cannot paint - the grey wash - is left out and said in the answer. The new row lands in the group the recipe names. Takes the right of the element.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('250', '22', 'CmdUpdate', 'Changes the columns given of file rows, by id; the pictures themselves are not touched. Takes the right of the elements they hang on.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('251', '22', 'CmdRemove', 'Deletes file rows by id. The pictures stay on the disk until the owner runs the idle-files audit: nothing in this store deletes a file from there. Takes the right of the elements.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('252', '22', 'CmdPos', 'Lays one group of one element in order - the order a template walks the pictures in. Takes the right of the element.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('134', '23', 'CmdTopic', 'Walks the goods of the sections named - the plain way to see what stands where. Searching by the columns of the map is CmdQuery.\n\nName the sections in topic_id, and topic_sub takes the whole branch under each of them; the Catalog tool answers the tree to pick them from. A section this person may not price is walked past, whatever the call names.\n\nThe goods come by id, and so does every page of them: a walk of many pages loses none and says none twice. Where a goods stands and at what place comes with it, in the rows of topic_store - sort by that if the order of the shop is what is wanted.\n\nA goods hanging in several of the sections walked is answered once. The answer is the one CmdQuery gives: the goods and the rows of topic_store they hang by - and found, the whole count of what stands there, whatever the page asked for.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('350', '23', 'CmdQuery', 'Finds the goods by a query written as json and answers them with the rows of topic_store they hang by.\n\nASKED FOR NOTHING - an empty query, or none at all - it answers its own signature instead: every table with every column and its type, and what may be asked of each. Nothing outside that list is taken, so a first call asks for it and the ones after are built by it.\n\nTHE SHAPE. A query starts from the root table of the sign and holds a list of conditions. A list is an AND, always. Four things may stand in it:\na condition - {"field": "price", "op": "between", "value": [1000, 5000]};\nan or - {"or": [ ..., ... ]};\na not - {"not": ...}, of one condition or of one nested table;\na nested table - {"topic_store": [ ... ]}, which means THERE IS such a row: every condition inside it holds on one and the same row. A table goes one level deep only, and only a table the sign marks nest.\n\nTHE SECTIONS are a nested table like any other: {"topic_store": [{"field": "topic_id", "op": "in", "value": [9, 10]}]}. The sections are named as they are - a whole branch is named section by section, and the Catalog tool answers the tree to build such a list from.\n\nNOTHING STANDS BESIDE THE ROOT TABLE. The page is a field of the call - limit and offset - and the goods come by id, page after page, so a walk of many pages loses none and says none twice. Sorting them any other way is done by whoever reads the answer. Whatever the page, the answer carries found - the whole count of what matched - so the size of a search is known without pulling it.\n\nTHE OPERATIONS come from the type of the column, and the sign names them: eq, in, between, ge, le for numbers, eq, between, ge, le for days, eq, in, like for words, eq for flags. between takes two values, in takes a list, the rest take one. like looks for a part of the text anywhere in it.\n\nAN EXAMPLE of the whole thing:\n{"store": [\n  {"field": "no_visible", "op": "eq", "value": false},\n  {"field": "price", "op": "between", "value": [1000, 5000]},\n  {"or": [ {"field": "status_key", "op": "in", "value": ["kExist", "kExistOrder"]},\n            {"field": "how", "op": "ge", "value": 1} ]},\n  {"topic_store": [ {"field": "topic_id", "op": "in", "value": [9, 10, 11]} ]},\n  {"not": {"topic_store": [ {"field": "topic_id", "op": "eq", "value": 5} ]}}\n]}\n\nThe goods of a list of ids are asked for the same way: {"store": [ {"field": "id", "op": "in", "value": [25, 26]} ]}.\n\nThe right stands beside the query and is not part of it: only the goods hanging in a section this person may place in are ever met, whatever the query says. The place a goods keeps in a section is written here and nowhere else: CmdUpdate moves a link, CmdPos lays a whole section in order.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('135', '23', 'CmdLink', 'Hangs goods into a section, each at the end of it. A goods already standing there is left as it is and said in the answer.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('136', '23', 'CmdUpdate', 'Moves links into another section, each at the end of it - the goods keep every other section they hang in. CmdTopic answers the links with their ids.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('137', '23', 'CmdUnlink', 'Deletes links by id: a goods loses that section and keeps every other it hangs in. A goods left hanging nowhere is seen by the Lost tool alone.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('138', '23', 'CmdPos', 'Lays the goods of one section in order - the order the storefront walks them by.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('139', '24', 'CmdList', 'Every goods hanging in no section, page after page. No field narrows it: this is the whole of what is lost, and found says how many that is. Searching among them - by a code, by a part of a name, by id - is CmdQuery.\n\nThe goods come by id, so a walk of many pages loses none and says none twice.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('352', '24', 'CmdQuery', 'The same goods CmdList walks, narrowed by a query written as json.\n\nASKED FOR NOTHING - an empty query, or none at all - it answers its own signature instead: the columns of a goods and the type of each, and what may be asked of them. Nothing outside that list is taken.\n\nTHE SHAPE. A query starts from the root table of the sign and holds a list of conditions. A list is an AND, always. Three things may stand in it:\na condition - {"field": "name", "op": "like", "value": "Bosch"};\nan or - {"or": [ ..., ... ]};\na not - {"not": ...}, of one condition.\nNothing nests here: a goods hanging nowhere has no sections, and the rest of what hangs on it belongs to the other tools of the Goods branch.\n\nBESIDE THE ROOT TABLE nothing stands. The page is a field of the call - limit and offset - and the goods come by id. Whatever the page, the answer carries found, the whole count of what matched.\n\nTHE OPERATIONS come from the type of the column, and the sign names them: eq, in for the id, eq, in, like for words. like looks for a part of the text anywhere in it.\n\nAN EXAMPLE:\n{"store": [\n  {"or": [ {"field": "name", "op": "like", "value": "Bosch"},\n            {"field": "code_shop", "op": "like", "value": "F-0"} ]}\n]}\n\nThe goods of a list of ids are asked for the same way: {"store": [ {"field": "id", "op": "in", "value": [25, 26]} ]}.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('140', '24', 'CmdLink', 'Hangs a lost goods back into a section, at the end of it.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('141', '24', 'CmdRemove', 'Deletes a lost goods from the store for good, with everything hanging on it - its characteristics, its parameters, its files. It goes at once, on this one call: no Recovery of the program brings it back. Orders keep their lines - an order line carries its own copy of the name.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('253', '27', 'CmdList', 'Reads the profiles, every recipe in plain words.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('254', '27', 'CmdAdd', 'Adds a profile: the name and the two sides are asked for, the rest of the recipe takes its defaults. The word of the profile is what CmdMake of the Files tool runs by.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('255', '27', 'CmdUpdate', 'Changes the fields given of one profile, the rest stay as they were; rename gives it a new word.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('256', '27', 'CmdRemove', 'Takes one profile out of the registry; a profile the program relies on is refused. Pictures already derived by it stay where they hang.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('344', '29', 'CmdTopic', 'Walks the goods of the sections named - the plain way to see what stands where. Searching by the columns of the map is CmdQuery.\n\nName the sections in topic_id, and topic_sub takes the whole branch under each of them; the Catalog tool answers the tree to pick them from. A section this person may not browse is walked past, whatever the call names.\n\nThe goods come by id, and so does every page of them: a walk of many pages loses none and says none twice. Where a goods stands and at what place comes with it, in the rows of topic_store - sort by that if the order of the shop is what is wanted.\n\nA goods hanging in several of the sections walked is answered once. The answer carries the goods and the sections they hang in - and found, the whole count of what stands there, whatever the page asked for.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('346', '29', 'CmdQuery', 'Finds the goods by a query written as json and answers them with the sections they hang in.\n\nASKED FOR NOTHING - an empty query, or none at all - it answers its own signature instead: every table with every column and its type, and what may be asked of each. Nothing outside that list is taken, so a first call asks for it and the ones after are built by it.\n\nTHE SHAPE. A query starts from the root table of the sign and holds a list of conditions. A list is an AND, always. Four things may stand in it:\na condition - {"field": "price", "op": "between", "value": [1000, 5000]};\nan or - {"or": [ ..., ... ]};\na not - {"not": ...}, of one condition or of one nested table;\na nested table - {"topic_store": [ ... ]}, which means THERE IS such a row: every condition inside it holds on one and the same row. A table goes one level deep only, and only a table the sign marks nest.\n\nTHE SECTIONS are that nested table: {"topic_store": [{"field": "topic_id", "op": "in", "value": [9, 10]}]}. The sections are named as they are - a whole branch is named section by section, and the Catalog tool answers the tree to build such a list from; CmdTopic takes a branch by itself.\n\nNOTHING STANDS BESIDE THE ROOT TABLE. The page is a field of the call - limit and offset - and the goods come by id, page after page, so a walk of many pages loses none and says none twice. Sorting them any other way is done by whoever reads the answer. Whatever the page, the answer carries found - the whole count of what matched - so the size of a search is known without pulling it.\n\nTHE OPERATIONS come from the type of the column, and the sign names them: eq, in, between, ge, le for numbers, eq, between, ge, le for days, eq, in, like for words, eq for flags. between takes two values, in takes a list, the rest take one. like looks for a part of the text anywhere in it.\n\nAN EXAMPLE of the whole thing:\n{"store": [\n  {"field": "no_visible", "op": "eq", "value": false},\n  {"field": "price", "op": "between", "value": [1000, 5000]},\n  {"or": [ {"field": "status_key", "op": "in", "value": ["kExist", "kExistOrder"]},\n            {"field": "brand_id", "op": "in", "value": [1, 2]} ]},\n  {"topic_store": [ {"field": "topic_id", "op": "in", "value": [9, 10, 11]} ]},\n  {"not": {"topic_store": [ {"field": "topic_id", "op": "eq", "value": 5} ]}}\n]}\n\nThe goods of a list of ids are asked for the same way: {"store": [ {"field": "id", "op": "in", "value": [25, 26]} ]}.\n\nThe right stands beside the query and is not part of it: only the goods hanging in a section this person may browse are ever met, whatever the query says. Nothing here is ever written: this tool reads the catalogue, and the tools of the Goods branch shape it.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('234', '31', 'CmdList', 'Reads the whole registry - the tree of the codes and every value standing under them, two tables in one answer. The tree itself belongs to the platform and is read here, never written.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('235', '31', 'CmdValueAdd', 'Adds a value to a code, at the end of its list.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('236', '31', 'CmdValueUpdate', 'Changes the columns given of values, by id. The text of a value the platform relies on (sys_key) may be changed; its name may not.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('237', '31', 'CmdValueRemove', 'Deletes values by id. What already holds such a value keeps the word: nothing of the shop is rewritten behind it. A value the platform relies on (sys_key) is refused.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('238', '31', 'CmdValuePos', 'Lays the values of one code in order.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('201', '32', 'CmdList', 'Reads the whole tree of the groups, the rights on them and every setting in them - three tables.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('202', '32', 'CmdAdd', 'Adds a group under a parent, or at the top of the tree when parent_id is 0.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('203', '32', 'CmdUpdate', 'Changes the columns given of groups, by id - what the call leaves out stays as it was.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('204', '32', 'CmdMove', 'Moves a group under another parent, with its branch.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('205', '32', 'CmdRemove', 'Deletes groups by id, with the branch under them, the settings in them and the rights on them. The first call counts what goes, the second one does it.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('206', '32', 'CmdValueAdd', 'Adds a setting to a group, at the end of its list.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('207', '32', 'CmdValueUpdate', 'Changes the columns given of settings, by id - what the call leaves out stays as it was.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('208', '32', 'CmdValueRemove', 'Deletes settings by id. The group they stood in stays.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('209', '32', 'CmdValuePos', 'Lays the settings of one group in order.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('210', '32', 'CmdRightAdd', 'Grants the sight of groups, to a person or to a group of people: one row of self_key_right on each of them. One of user_id and group_id, never both.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('211', '32', 'CmdRightUpdate', 'Changes the columns given of the rows of self_key_right, by id - CmdList answers them with their ids.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('212', '32', 'CmdRightRemove', 'Deletes the rows of self_key_right by id. A group with no rights on it is seen by nobody.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('261', '33', 'CmdList', 'Reads the currency table whole.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('262', '33', 'CmdAdd', 'Adds a currency at the end of the list. The rate comes as 1 when the call leaves it out - the program adds one the same way - so give the real multiplex right away.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('263', '33', 'CmdUpdate', 'Changes the columns given of currencies, by id - what the call leaves out stays as it was.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('264', '33', 'CmdRemove', 'Deletes currencies by id. The first call counts the goods priced in them, the second one does it: their *_curr_id columns are emptied, so those prices read as the base currency, and the sums already written into orders stay as written.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('265', '33', 'CmdPos', 'Lays the list of the currencies in order.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('266', '34', 'CmdListCut', 'Reads the groups and the providers standing in them - two tables. The warehouses and the option rows come with CmdListFull.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('355', '34', 'CmdListFull', 'Reads the family whole - the groups, the providers, the warehouses of every provider and the option rows standing on providers and warehouses: five tables in one answer.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('267', '34', 'CmdAdd', 'Adds a provider at the end of the list.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('268', '34', 'CmdUpdate', 'Changes the columns given of providers, by id - what the call leaves out stays as it was.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('269', '34', 'CmdRemove', 'Deletes providers by id. The first call counts the goods and the currencies pointing at them, the second one does it: store.provider_id and currency.provider_id are emptied, the rows that hung on the providers are swept by the map of the engine, and what orders already carry stays as written.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('270', '34', 'CmdPos', 'Lays the list of the providers in order.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('271', '34', 'CmdGroupAdd', 'Adds a group of providers at the end of the list.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('272', '34', 'CmdGroupUpdate', 'Changes the columns given of groups, by id.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('273', '34', 'CmdGroupRemove', 'Deletes groups by id. A group that providers still stand in is refused - move them out of it first.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('274', '34', 'CmdGroupPos', 'Lays the list of the groups in order.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('275', '34', 'CmdKeyAdd', 'Sets an option on providers: one row of provider_key_set on each of them. The option and its value must stand in the tree of the provider options, and a stray id is refused.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('276', '34', 'CmdKeyUpdate', 'Changes the columns given of the rows of provider_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('277', '34', 'CmdKeyRemove', 'Deletes the rows of provider_key_set by id. The option itself stays in the tree.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('309', '34', 'CmdStockAdd', 'Adds a warehouse to a provider, at the end of its list. A goods keeps its count on a warehouse, and the Price tool writes those counts.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('310', '34', 'CmdStockUpdate', 'Changes the columns given of warehouses, by id - what the call leaves out stays as it was. A warehouse moves to another provider by provider_id, and the counts of the goods move with it.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('311', '34', 'CmdStockRemove', 'Deletes warehouses by id. The first call counts the rows of the goods standing on them, the second one does it: those rows are swept by the map of the engine, while the count a goods keeps in its own card stays as it is.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('312', '34', 'CmdStockPos', 'Lays the warehouses of one provider in order.', '17');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('313', '34', 'CmdStockKeyAdd', 'Sets an option on warehouses: one row of provider_stock_key_set on each of them. The option and its value must stand in the tree of the warehouse options, and a stray id is refused. The tree itself is declared in the registry of the additional options, place provider_stock.', '18');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('314', '34', 'CmdStockKeyUpdate', 'Changes the columns given of the rows of provider_stock_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree.', '19');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('315', '34', 'CmdStockKeyRemove', 'Deletes the rows of provider_stock_key_set by id. The option itself stays in the tree.', '20');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('278', '35', 'CmdListCut', 'Reads the discount groups and nothing beside them. The rules standing in them come with CmdListFull.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('356', '35', 'CmdListFull', 'Reads the discount groups together with every rule standing in them - two tables in one answer. A group with no rule gives nothing away.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('279', '35', 'CmdAdd', 'Adds a discount group at the end of the list. It gives nothing away until a rule stands in it.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('280', '35', 'CmdUpdate', 'Changes the columns given of groups, by id - what the call leaves out stays as it was.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('281', '35', 'CmdRemove', 'Deletes discount groups by id. The first call counts the goods priced by them, the second one does it: store.disc_group_id is emptied, so those goods sell without a discount, and the rules of the groups go with them.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('282', '35', 'CmdPos', 'Lays the list of the discount groups in order.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('283', '35', 'CmdRateAdd', 'Adds a rule to discount groups: one row of disc_rate on each of them. The rules of one group stand by from_sum, so several of them make a ladder; the days are opened the way the program opens them - from now, for ten years.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('284', '35', 'CmdRateUpdate', 'Changes the columns given of rules, by id - CmdList answers them with their ids. A rule does not move to another group: take it back and add it anew.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('285', '35', 'CmdRateRemove', 'Deletes rules by id. The group stays, and gives nothing away while it holds no rule.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('287', '37', 'CmdAdd', 'Loads goods with their sections, their characteristics and their parameters in one call. Each stream is a list of rows - the array itself, or {"file": "C:\\\\...\\\\rows.jsonl"} on your machine, one row per line. A field written as store.column, info.column or param.column is what every row of that stream takes unless the row names its own. Every section must be yours by both the Description and the Price right. A goods is born hidden and kAbsent, the way the program births one. The answer gives a row per goods - your ref beside the id it was born with - and that is what the Files tool takes for the pictures. Try three rows and look at the goods with your own eyes - and at the timing of debug: true - before the thousand goes.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('288', '38', 'CmdAdd', 'Hangs a pack of files on their elements and paints a derived picture where a profile asks for one. A file whose element is not yours goes back at once and is said in the answer. Takes the right of those elements, and no setting right with it: a derived picture is a file, not a setting.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('289', '40', 'CmdList', 'Reads the options declared for one place and every value they keep - two tables. The tree comes whole: a registry of a shop is small, and key_id with value_id are filled from it.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('290', '40', 'CmdKeyAdd', 'Declares an option in one place, under a parent - 0 puts it at the top of the tree. A folder only groups others and keeps no values of its own.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('291', '40', 'CmdKeyUpdate', 'Changes the columns given of options, by id - what the call leaves out stays as it was. A skey goes to a single id: the name of an option is its own.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('292', '40', 'CmdKeyMove', 'Moves an option under another parent, with the branch under it.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('293', '40', 'CmdKeyRemove', 'Deletes options by id, with the branch under them, their values and the rows of the entities standing on them. The first call counts what goes, the second one does it.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('294', '40', 'CmdValueAdd', 'Adds a value to an option, at the end of its list. An option keeping no values is filled in by hand or by its mask; one keeping them becomes a list to pick from.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('295', '40', 'CmdValueUpdate', 'Changes the columns given of values, by id - what the call leaves out stays as it was. A skey goes to a single id and is weighed against the values of its own option.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('296', '40', 'CmdValueRemove', 'Deletes values by id. What stood on those values is swept by the map of the engine, so the rows of the entities lose the word they answered with. The first call counts, the second one does it.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('297', '40', 'CmdValuePos', 'Lays the values of one option in order.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('298', '41', 'CmdList', 'Reads the filters of every place and the value lists their parameters pick from - both tables whole.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('299', '41', 'CmdAdd', 'Adds a filter at the end of the list of its place. The query is the developer\'s own and is kept as it comes.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('300', '41', 'CmdUpdate', 'Changes the columns given of filters, by id - what the call leaves out stays as it was.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('301', '41', 'CmdRemove', 'Deletes filters by id. A profile of the window that asked for one keeps its name and finds nothing behind it.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('302', '41', 'CmdPos', 'Lays the filters of one place in order.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('303', '41', 'CmdParamAdd', 'Adds a value list at the end of the list. The alias is the name a filter parameter calls it by after the dog.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('304', '41', 'CmdParamUpdate', 'Changes the columns given of value lists, by id - what the call leaves out stays as it was.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('305', '41', 'CmdParamRemove', 'Deletes value lists by id. A parameter written as :NAME@ALIAS of one of them asks for a number by hand again.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('306', '41', 'CmdParamPos', 'Lays the value lists in order.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('307', '42', 'CmdList', 'Reads the settings this person may work with - code, name, description, entry mask, value. A branch nobody opened for them answers nothing at all, the way the window of the program shows nothing there.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('308', '42', 'CmdUpdate', 'Writes the value of one setting, by its code. The engine weighs the right and takes the lock itself, so a refusal here says which of the three it was: no such setting, not this person\'s branch, or the table is in work.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('316', '43', 'CmdListCut', 'Reads the tax groups and nothing beside them. The rates, the areas, their rules and the option rows come with CmdListFull.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('357', '43', 'CmdListFull', 'Reads the whole of the taxes - the groups, their rates, the tree of the areas, the rules tying a rate to an area and the option rows on the areas: five tables in one answer.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('317', '43', 'CmdAdd', 'Adds a tax group at the end of the list. It takes nothing off a goods until a rate stands in it.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('318', '43', 'CmdUpdate', 'Changes the columns given of tax groups, by id - what the call leaves out stays as it was.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('319', '43', 'CmdRemove', 'Deletes tax groups by id. The first call counts what goes with them and how many goods point at them, the second one does it: tax_group_id is emptied on those goods, and the rates of the groups - with the rules standing on those rates - are swept by the map of the engine.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('320', '43', 'CmdPos', 'Lays the list of the tax groups in order.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('321', '43', 'CmdRateAdd', 'Adds a rate to a tax group, at the end of its list. A rate takes a per cent, a sum, or both - what the program shows is what stands in the columns.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('322', '43', 'CmdRateUpdate', 'Changes the columns given of rates, by id - what the call leaves out stays as it was. A rate moves to another group by group_id, and the rules that named it move with it.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('323', '43', 'CmdRateRemove', 'Deletes rates by id. The first call counts the rules standing on them, the second one does it - those rules go with the rates, swept by the map of the engine.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('324', '43', 'CmdAreaAdd', 'Adds an area under a parent, or at the top of the tree when parent_id is 0. A folder only groups others; an area meets a rate through a rule, and an area with no rule of its own follows the areas above it.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('325', '43', 'CmdAreaUpdate', 'Changes the columns given of areas, by id - what the call leaves out stays as it was.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('326', '43', 'CmdAreaMove', 'Moves an area under another parent, with the branch under it.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('327', '43', 'CmdAreaRemove', 'Deletes areas by id, with the branch under them. The first call counts what goes - the rules of those areas and the option rows set on them - the second one does it.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('328', '43', 'CmdRuleAdd', 'Ties a rate to an area: one rule. Left plain the rule takes what its rate says; with rule_custom it takes the per cent and the sum written here instead.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('329', '43', 'CmdRuleUpdate', 'Changes the columns given of rules, by id - what the call leaves out stays as it was. A rule moves to another area or another rate by area_id and rate_id.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('330', '43', 'CmdRuleRemove', 'Deletes rules by id. The area keeps whatever the areas above it say, and the rate stays in its group.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('331', '43', 'CmdKeyAdd', 'Sets an option on areas: one row of tax_area_key_set on each of them. The option and its value must stand in the tree of the area options, and a stray id is refused.', '17');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('332', '43', 'CmdKeyUpdate', 'Changes the columns given of the rows of tax_area_key_set, by id - CmdList answers them with their ids. A row keeps whatever the call leaves out, and the pair it will stand with is weighed against the tree.', '18');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('333', '43', 'CmdKeyRemove', 'Deletes the rows of tax_area_key_set by id. The option itself stays in the tree.', '19');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('375', '45', 'CmdList', 'Reads the promo blocks whole - the tree, the texts of every block, the goods it gathers, the places it hangs in and the option rows set: five tables in one answer.', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('377', '45', 'CmdAdd', 'Adds a promo block under a parent, or at the top of the tree when parent_id is 0. A folder only groups other blocks and shows nothing of its own.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('378', '45', 'CmdUpdate', 'Changes the columns given of promo blocks, by id - what the call leaves out stays as it was.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('379', '45', 'CmdMove', 'Moves a promo block under another parent, its whole branch with it.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('380', '45', 'CmdRemove', 'Deletes promo blocks by id, with the branches under them. The first call counts what goes, depend does it.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('381', '45', 'CmdTextAdd', 'Adds a text to promo blocks: one row of advert_text on every block named.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('382', '45', 'CmdTextUpdate', 'Changes the columns given of the texts, by id.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('383', '45', 'CmdTextRemove', 'Deletes texts by id. The pictures hanging on them go by depend.', '8');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('384', '45', 'CmdTextPos', 'Lays the texts of one block in order.', '9');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('385', '45', 'CmdGoodsAdd', 'Puts goods into promo blocks: one row of advert_goods on every block named. The goods itself is elem_id, and the Browser tool answers the ids.', '10');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('386', '45', 'CmdGoodsUpdate', 'Changes the columns given of the rows of advert_goods, by id.', '11');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('387', '45', 'CmdGoodsRemove', 'Deletes the rows of advert_goods by id. The goods themselves stay as they are.', '12');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('388', '45', 'CmdGoodsPos', 'Lays the goods of one block in order.', '13');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('389', '45', 'CmdLinkAdd', 'Hangs promo blocks on an object of the shop: one row of advert_link on every block named. obj_key says what kind of object it is and param_id names it - a section, a goods, an attribute.', '14');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('390', '45', 'CmdLinkUpdate', 'Changes the columns given of the links, by id.', '15');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('391', '45', 'CmdLinkRemove', 'Deletes links by id. The objects they pointed at stay as they are.', '16');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('392', '45', 'CmdLinkPos', 'Lays the links of one block in order.', '17');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('393', '45', 'CmdKeyAdd', 'Sets an option on promo blocks: one row of advert_key_set on every block named. The options are declared in the registry of the additional options, place advert.', '18');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('394', '45', 'CmdKeyUpdate', 'Changes the columns given of the rows of advert_key_set, by id.', '19');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('395', '45', 'CmdKeyRemove', 'Deletes the rows of advert_key_set by id. The option itself stays in its tree.', '20');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('396', '46', 'CmdQuery', 'Finds the orders by a query written as json and answers each of them whole - the head with its code, the current version, the goods in it, the options of the order, the options standing on every goods, and the fields the buyer filled.\n\nASKED FOR NOTHING - an empty query, or none at all - it answers its own signature instead: every table with every column and its type, and what may be asked of each. Nothing outside that list is taken, so a first call asks for it and the ones after are built by it.\n\nTHE SHAPE. A query starts from the root table of the sign and holds a list of conditions. A list is an AND, always. Four things may stand in it:\na condition - {"field": "code", "op": "like", "value": "781"};\nan or - {"or": [ ..., ... ]};\na not - {"not": ...}, of one condition or of one nested table;\na nested table - {"orders_option": [ ... ]}, which means THERE IS such a row: every condition inside it holds on one and the same row. A table goes one level deep only, and only a table the sign marks nest.\n\nONE VERSION OF ONE ORDER. The root is the order itself - its id, its code, the day it was made. Everything else nests, and every nested table stands on the version the order is at now, so an order is one row and never many; the versions it stood at before are not reached from here. The money and the buyer of the order are orders_version: {"orders_version": [{"field": "total_sum", "op": "ge", "value": 1000}]}.\n\nTHE STATUS AND EVERY OTHER OPTION is a row of orders_option, and the key of a value is what to look by: {"orders_option": [{"field": "option_skey", "op": "eq", "value": "status"}, {"field": "value_skey", "op": "eq", "value": "new"}]}. Both conditions hold on one row, which is what makes it the status and not any option that happens to carry that value.\n\nTHE BUYER is asked for the same way, by his fields: {"orders_client_field": [{"field": "field_skey", "op": "eq", "value": "phone"}, {"field": "value_txt", "op": "like", "value": "380 67"}]}. The keys of the fields and of the options are the ones the shop was set up with - a first answer of any order shows them all.\n\nTHE GOODS of an order are a nested table too: {"orders_store": [{"field": "store_id", "op": "in", "value": [25, 26]}]} finds the orders one of those goods was bought in. The row keeps the goods as it was then - its name, its codes, its price - so an order reads the same after the goods itself has changed or gone.\n\nNOTHING STANDS BESIDE THE ROOT TABLE. The page is a field of the call - limit and offset - and the orders come by id, page after page, so a walk of many pages loses none and says none twice. Whatever the page, the answer carries found - the whole count of what matched.\n\nTHE OPERATIONS come from the type of the column, and the sign names them: eq, in, between, ge, le for numbers, eq, between, ge, le for days, eq, in, like for words, eq for flags.\n\nAN EXAMPLE of the whole thing:\n{"orders": [\n  {"field": "date_time", "op": "ge", "value": "2026-08-01"},\n  {"orders_version": [ {"field": "total_sum", "op": "ge", "value": 1000} ]},\n  {"orders_option": [ {"field": "option_skey", "op": "eq", "value": "status"},\n                      {"field": "value_skey", "op": "in", "value": ["new", "work"]} ]},\n  {"not": {"orders_option": [ {"field": "option_skey", "op": "eq", "value": "delivery"},\n                              {"field": "value_skey", "op": "eq", "value": "pickup"} ]}}\n]}', '1');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('397', '46', 'CmdCreate', 'Answers a blank version of a new order: the buyer fields of the shop empty, the order options at their defaults, no goods. Shape it and save with CmdEdit - the order and its buyer are born there. The array is the same one CmdLoad answers, so the circle of the commands is one whatever the order began as.', '2');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('398', '46', 'CmdLoad', 'Answers the version the order stands at now as one array: the head fields with parent_version_id - the version this array grew from; client - the buyer fields with their values; store - the goods rows, each carrying its snapshot of the goods and its store_option list; option - the order options with the sums they add. Change the array yourself or hand it to the commands; parent_version_id is what CmdEdit weighs the order by, so an array held too long meets VERSION_ERROR there and is loaded afresh.', '3');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('399', '46', 'CmdGoodsAdd', 'Puts a goods into the version: reads it from the shop as it is now - the prices brought to the shop currency, the codes, the name - hangs the goods options of the shop on it at their defaults, and answers the version grown by that row. A goods already in the version grows its amount instead. The base itself is untouched until CmdEdit.', '4');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('400', '46', 'CmdGoodsRemove', 'Takes a goods out of the version and answers what is left; a goods the version does not hold is refused by name. The base itself is untouched until CmdEdit.', '5');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('401', '46', 'CmdOptionSet', 'Sets an order option by the keys of the registry: the names, the sum and the money words of the value come along by themselves. An unknown key is refused with the list of what the shop holds. The base itself is untouched until CmdEdit.', '6');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('402', '46', 'CmdCalc', 'Counts the version the way the shop counts an order - the discounts of the goods, then the option sums in their order - and answers the version with total_sum set. What the shop refuses to take - a blocked pair of values, an option not yours to change - comes back as the refusal it would meet at saving. Nothing is written; run it before CmdEdit to see the money and the refusals early.', '7');
INSERT INTO {DBNICK}_agent_tool_command (id, tool_id, name, descr, pos) VALUES ('403', '46', 'CmdEdit', 'Saves the version as the new version of its order - or births the order and its buyer when order_id is empty - and answers the order id. The shop verifies before it writes: the blocked pairs, the option rights, the limits; and an array grown from a version the order no longer stands at is refused as VERSION_ERROR - load it afresh and carry the change over. This is the only command of the circle that writes.', '8');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('68', '73', 'id', 'id of the goods, or several of them', 'int/json', '1', '', '1');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('76', '73', 'provider_id', 'id of the supplier; 0 for none', 'int', '0', '', '2');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('410', '73', 'brand_id', 'id of the brand; 0 for none', 'int', '0', '', '3');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('411', '73', 'code_shop', 'the article of the shop', 'str', '0', '', '4');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('412', '73', 'code_prov', 'the article of the supplier', 'str', '0', '', '5');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('413', '73', 'code_made', 'the article of the maker', 'str', '0', '', '6');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('415', '73', 'meas', 'the unit it is sold in', 'str', '0', '', '7');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('414', '73', 'name', 'the name of the goods, the one a buyer reads', 'str', '0', '', '8');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('409', '73', 'no_visible', 'true - the goods is off the storefront, false - it is shown', 'bool', '0', '', '9');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('89', '73', 'status_key', 'a value of STORE_STATUS_KEY - whether the goods is in stock', 'str', '0', '', '10');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('416', '73', 'kind_key', 'a value of STORE_KIND_KEY', 'str', '0', '', '11');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('417', '73', 'state_key', 'a value of STORE_STATE_KEY', 'str', '0', '', '12');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('90', '73', 'rating', 'the rating of the goods, from -2 to 2', 'int', '0', '', '13');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('85', '73', 'disc_group_id', 'id of the discount group; 0 for none', 'int', '0', '', '14');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('1433', '73', 'tax_group_id', 'id of the tax group of the goods - the Taxes tool answers the groups', 'int', '0', '', '15');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('86', '73', 'how', 'how many are in stock', 'int', '0', '', '16');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('77', '73', 'pprice', 'the price of the supplier', 'float', '0', '', '17');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('78', '73', 'pprice_curr_id', 'id of the currency of the price of the supplier', 'int', '0', '', '18');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('79', '73', 'rprice', 'the price the supplier recommends', 'float', '0', '', '19');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('80', '73', 'rprice_curr_id', 'id of the currency of the recommended price', 'int', '0', '', '20');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('70', '73', 'price', 'the price a buyer pays', 'float', '0', '', '21');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('71', '73', 'price_curr_id', 'id of the currency of the price', 'int', '0', '', '22');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('72', '73', 'price2', 'the second price', 'float', '0', '', '23');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('73', '73', 'price2_curr_id', 'id of the currency of price2', 'int', '0', '', '24');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('74', '73', 'price3', 'the third price', 'float', '0', '', '25');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('75', '73', 'price3_curr_id', 'id of the currency of price3', 'int', '0', '', '26');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('418', '73', 'relate_id', 'id of another goods this one is related to; 0 for none', 'int', '0', '', '27');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('81', '73', 'relate_type', 'how the price and the price of the supplier follow one another: 0 none, 1 the price leads, 2 the price of the supplier, 3 the price the supplier recommends', 'int', '0', '', '28');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('82', '73', 'relate_proc', 'the per cent that count adds to the base, or takes off it', 'float', '0', '', '29');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('83', '73', 'proc_price2', 'the per cent price2 is counted off the price', 'float', '0', '', '30');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('84', '73', 'proc_price3', 'the per cent price3 is counted off the price', 'float', '0', '', '31');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('87', '73', 'min_order', 'the least a buyer may order', 'int', '0', '', '32');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('88', '73', 'step_order', 'the step the count goes by', 'int', '0', '', '33');
INSERT INTO {DBNICK}_agent_tool_param (id, command_id, name, descr, value_type, value_req, value_def, pos) VALUES ('91', '73', 'in_xml', 'true - the goods goes into the xml feed', 'bool', '0', '', '34');
